__mods["js/modules/index.js"] = (function () {
// Registry of module definitions. Imported by both the UI and the worklet.
const tripleVco = __mods["js/modules/triple-vco.js"].default;
const dualFilter = __mods["js/modules/dual-filter.js"].default;
const envelopeShaper = __mods["js/modules/envelope-shaper.js"].default;
const dualRingMod = __mods["js/modules/dual-ring-mod.js"].default;
const sequencer = __mods["js/modules/sequencer.js"].default;
const filterbank = __mods["js/modules/filterbank.js"].default;
const output = __mods["js/modules/output.js"].default;
const keyboard = __mods["js/modules/keyboard.js"].default;

const MODULE_DEFS = {
  [tripleVco.type]: tripleVco,
  [dualFilter.type]: dualFilter,
  [envelopeShaper.type]: envelopeShaper,
  [dualRingMod.type]: dualRingMod,
  [sequencer.type]: sequencer,
  [filterbank.type]: filterbank,
  [output.type]: output,
  [keyboard.type]: keyboard,
};

// Order shown in the "add module" menu. { separator: true } draws a divider.
const MODULE_MENU = [
  { type: 'triple-vco', label: 'Triple VCO' },
  { type: 'dual-filter', label: 'Dual Filter/Oscillator' },
  { type: 'envelope-shaper', label: 'Envelope Shaper' },
  { type: 'dual-ring-mod', label: 'Dual Ring Modulator' },
  { type: 'sequencer', label: 'Sequential Voltage Source' },
  { type: 'filterbank', label: 'VCF Filterbank' },
  { separator: true },
  { type: 'output', label: 'OUTPUT' },
  { type: 'keyboard', label: 'KEYBOARD / CV' },
];

function findControl(def, id) {
  return def.controls.find(c => c.id === id);
}

function findJack(def, id) {
  return def.jacks.find(j => j.id === id);
}

function defaultParams(def) {
  const p = {};
  for (const c of def.controls) p[c.id] = c.def;
  return p;
}

return { MODULE_DEFS, MODULE_MENU, findControl, findJack, defaultParams };
})();

